   330→  {
   331→    final ContextFactory contextFactory = ContextFactory.getGlobal();
   332→    Context context = contextFactory.enterContext();
   333→    context.setOptimizationLevel(JavaScriptConfig.DEFAULT_OPTIMIZATION_LEVEL);
   334→
   335→    final ScriptableObject scope = context.initStandardObjects();
   336→
   337→    final Function fnAggregate = context.compileFunction(scope, aggregate, "aggregate", 1, null);
   338→    final Function fnReset = context.compileFunction(scope, reset, "reset", 1, null);
   339→    final Function fnCombine = context.compileFunction(scope, combine, "combine", 1, null);
   340→    Context.exit();
   341→
   342→    return new JavaScriptAggregator.ScriptAggregator()
   343→    {
   344→      @Override
   345→      public double aggregate(final double current, final BaseObjectColumnValueSelector[] selectorList)
   346→      {
   347→        Context cx = Context.getCurrentContext();
   348→        if (cx == null) {
   349→          cx = contextFactory.enterContext();
   350→
   351→          // Disable primitive wrapping- we want Java strings and primitives to behave like JS entities.
   352→          cx.getWrapFactory().setJavaPrimitiveWrap(false);
   353→        }
   354→
   355→        final int size = selectorList.length;
   356→        final Object[] args = new Object[size + 1];
   357→
   358→        args[0] = current;
   359→        for (int i = 0; i < size; i++) {
   360→          final BaseObjectColumnValueSelector selector = selectorList[i];
   361→          if (selector != null) {
   362→            final Object arg = selector.getObject();
   363→            if (arg != null && arg.getClass().isArray()) {
   364→              // Context.javaToJS on an array sort of works, although it returns false for Array.isArray(...) and
   365→              // may have other issues too. Let's just copy the array and wrap that.
   366→              args[i + 1] = cx.newArray(scope, arrayToObjectArray(arg));
   367→            } else if (arg instanceof List) {
   368→              // Using toArray(Object[]), instead of just toArray(), because Arrays.asList()'s impl and similar List
   369→              // impls could clone the underlying array in toArray(), that could be not Object[], but e. g. String[].
   370→              args[i + 1] = cx.newArray(scope, ((List) arg).toArray(ObjectArrays.EMPTY_ARRAY));
   371→            } else {
   372→              args[i + 1] = Context.javaToJS(arg, scope);
   373→            }
   374→          }
   375→        }
   376→
   377→        final Object res = fnAggregate.call(cx, scope, scope, args);
   378→        return Context.toNumber(res);
   379→      }
